<?php
namespace App\Http\Controllers; use App\Models\{TrainingQuestion,TrainingTopic}; use Illuminate\Http\Request; use Illuminate\Validation\ValidationException;
class TrainingQuestionController extends Controller{public function index(){ $company=auth()->user()->company_id;$topics=TrainingTopic::availableTo($company)->get();$questions=TrainingQuestion::forCompany($company)->with(['topic','options'])->get();return view('training.questions.index',compact('topics','questions'));}public function store(Request$r){$d=$r->validate(['training_topic_id'=>'required|exists:training_topics,id','question_text'=>'required|string|max:3000','question_type'=>'required|in:single_choice,multiple_choice,true_false','explanation'=>'nullable|string|max:3000','default_points'=>'required|numeric|min:0.01|max:1000','is_critical'=>'nullable|boolean','options'=>'required|array|min:2','options.*'=>'required|string|max:1000','correct_options'=>'required|array|min:1','correct_options.*'=>'integer|min:0']);$topic=TrainingTopic::availableTo($r->user()->company_id)->findOrFail($d['training_topic_id']);$correct=array_unique($d['correct_options']);if($d['question_type']!=='multiple_choice'&&count($correct)!==1)throw ValidationException::withMessages(['correct_options'=>'Este tipo de pregunta requiere una sola respuesta correcta.']);foreach($correct as$i)if(!array_key_exists($i,$d['options']))throw ValidationException::withMessages(['correct_options'=>'La respuesta correcta seleccionada no existe.']);$q=TrainingQuestion::create(['company_id'=>$r->user()->company_id,'training_topic_id'=>$topic->id,'question_text'=>$d['question_text'],'question_type'=>$d['question_type'],'explanation'=>$d['explanation']??null,'default_points'=>$d['default_points'],'is_critical'=>$d['is_critical']??false,'is_active'=>true,'created_by'=>$r->user()->id]);foreach($d['options'] as$i=>$text)$q->options()->create(['option_text'=>$text,'is_correct'=>in_array($i,$correct),'sort_order'=>$i+1]);return back()->with('success','Pregunta creada.');}}
